SELECT CONCAT(
           '29300000',
           COALESCE(
               MAX(CAST(SUBSTRING(group_id, 9) AS UNSIGNED)),
               0
           ) + 1
       ) AS next_group_id
FROM smartbusmngdb.sbm_operator
WHERE group_id LIKE '29300000%';

